// Block (composition) — a ready-to-use sign-in form assembled from Components.
// Contract: docs/rules/block-contract.md. Arranges only (Stack for layout);
// composes Form/TextField/Button/Alert. Owns no Component look; mints no tokens.
import type { FormEvent, Ref } from "react";
import { Form } from "../components/Form";
import { TextField } from "../components/TextField";
import { Button } from "../components/Button";
import { Link } from "../components/Link";
import { Alert } from "../components/Alert";
import { Stack } from "../layouts/Stack";
import "./LoginForm.css";

export interface LoginFormProps {
  /** Heading shown above the fields. */
  heading?: string;
  /** Called with the entered credentials on submit. */
  onSubmit?: (values: { email: string; password: string }) => void;
  /** Form-level error (e.g. bad credentials), shown above the fields. */
  errorMessage?: string;
  /** Puts the submit button in a pending state and blocks re-submit. */
  isPending?: boolean;
  /** Where "Forgot password?" goes. Omit to show no recovery link. */
  forgotPasswordHref?: string;
  /** Where "Sign up" goes, offered under the submit for a person without an account. */
  signUpHref?: string;
  className?: string;
  ref?: Ref<HTMLFormElement>;
}

export function LoginForm({
  heading = "Sign in",
  onSubmit,
  errorMessage,
  isPending,
  forgotPasswordHref,
  signUpHref,
  className,
  ref,
}: LoginFormProps) {
  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    onSubmit?.({
      email: String(data.get("email") ?? ""),
      password: String(data.get("password") ?? ""),
    });
  };

  return (
    <Form isPending={isPending}
      ref={ref}
      onSubmit={handleSubmit}
      className={className ? `sd-loginform ${className}` : "sd-loginform"}
    >
      <Stack gap="large" className="sd-loginform__content">
        {heading && (
          <>
            <h1 className="sd-loginform__heading sd-type-headline-medium">{heading}</h1>
          </>
        )}
        {/* live="assertive": see `AlertProps.live` — submit failure is the case that earns it. */}
        {errorMessage && (
          <Alert variant="error" live="assertive">
            {errorMessage}
          </Alert>
        )}
        <Stack gap="medium" className="sd-loginform__fields">
          <TextField label="Email" name="email" type="email" autoComplete="email" isRequired />
          <TextField
            label="Password"
            name="password"
            type="password"
            autoComplete="current-password"
            isRequired
          />
          {forgotPasswordHref && (
            <>
              <p className="sd-loginform__forgot sd-type-label-medium">
                <Link href={forgotPasswordHref}>Forgot password?</Link>
              </p>
            </>
          )}
        </Stack>
        <Button size="large" type="submit" variant="primary" isPending={isPending}>
          Sign in
        </Button>
        {signUpHref && (
          <p className="sd-loginform__signup sd-type-body-medium">
            {"Don't have an account? "}
            <Link href={signUpHref}>Sign up</Link>
          </p>
        )}
      </Stack>
    </Form>
  );
}

/* LoginForm.css — .sd-loginform (Block)
   Arrangement only: fills the column it is given; the page sets that column on the grid
   (a Container span or a LayoutGrid item), never this Block.
   Component look is owned by Form/TextField/Button/Alert; grouping is via Stack.
   No new tokens. */
.sd-loginform {
  width: 100%;
}

.sd-loginform__heading {
  margin: 0;
}

/* The sign-up line is centred under the full-width submit. */
.sd-loginform__forgot,
.sd-loginform__signup {
  margin: 0;
}
.sd-loginform__signup {
  text-align: center;
}
